     4	import { ZimmProductPrice } from '.';
     5	
     6	const meta: Meta<typeof ZimmProductPrice> = {
     7	  title: 'Commerce/ZimmProductPrice',
     8	  component: ZimmProductPrice,
     9	  argTypes: {
    10	    price: { control: 'text' },
    11	  },
    12	};
    13	export default meta;
    14	
    15	type Story = StoryObj<typeof ZimmProductPrice>;
    16	
    17	// Purely visual — the atom renders a caller-formatted string and has no behaviour worth
    18	// asserting, so no `play`. Currency formatting lives at the page (`intl.formatNumber`).
    19	export const Default: Story = {
    20	  args: { price: '$795.00' },
    21	};
    22	
    23	export const AcrossStorefrontCurrencies: Story = {
    24	  name: 'Across storefront currencies',
