    28	    <Box display="flex" flexDirection="column" gap="s">
    29	      <ZimmProductPrice price="$795.00" />
    30	      <ZimmProductPrice price="£550.00" />
    31	      <ZimmProductPrice price="€650.00" />
    32	      <ZimmProductPrice price="HK$6,200.00" />
    33	    </Box>
    34	  ),
    35	};

