########## overrides/app/components/ui-kits/molecules/zimmProductContent/index.tsx
     1	import React from 'react';
     2	import { chakra, useStyleConfig } from '@chakra-ui/react';
     3	import { ZimmProductName } from 'app/components/ui-kits/atoms/zimmProductName';
     4	import { ZimmProductPrice } from 'app/components/ui-kits/atoms/zimmProductPrice';
     5	import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription';
     6	
     7	type ZimmProductContentProps = {
     8	  /** The product's display name. */
     9	  name: string;
    10	  /**
    11	   * Heading level for the name. Passed through rather than fixed here so the caller keeps
    12	   * control of the page's heading outline — see `ZimmProductName`.
    13	   */
    14	  headingLevel: 'h1' | 'h2' | 'h3';
    15	  /** Price, already formatted for the storefront's locale and currency by the caller. */
    16	  price: string;
    17	  /** Long description as authored in Business Manager. Omitted when the product has none. */
    18	  description?: string;
    19	};
    20	
    21	/**
    22	 * Molecule — the PDP text group: name, price, description.
    23	 *
    24	 * Model copy and the style code are deliberately *not* here. The design places them at the
    25	 * bottom of the column, after the accordions, so the page positions them itself rather than
    26	 * this molecule holding them and then having to unpick the order.
    27	 */
    28	export const ZimmProductContent = ({ name, headingLevel, price, description }: ZimmProductContentProps) => {
    29	  const styles = useStyleConfig('ZimmProductContent', {});
    30	
    31	  return (
    32	    <chakra.div __css={styles} data-testid="product-content">
    33	      <ZimmProductName name={name} as={headingLevel} />
    34	      <ZimmProductPrice price={price} />
    35	      <ZimmProductDescription description={description} />
    36	    </chakra.div>
    37	  );
    38	};
########## overrides/app/components/ui-kits/molecules/zimmProductContent/zimmProductContent.css.ts
     1	import type { SystemStyleObject } from '@chakra-ui/react';
     2	
     3	/**
     4	 * Recipe for the PDP `Content` group — the DS's own 218 x 82 frame holding name, price and
     5	 * description. Not an invented grouping.
     6	 *
     7	 * The 20px rhythm is a flex `gap`, not a margin on each child. Two reasons:
     8	 *
     9	 *  - It collapses correctly when an optional field is absent. `ZimmProductDescription` returns
    10	 *    `null` when the product has no description, so there is no second gap to suppress. A
    11	 *    per-child `marginBottom` would need the parent to know which children rendered, and would
    12	 *    leave a trailing gap when the last one did not.
    13	 *  - It cannot be out-specified by a child. An adjacent-sibling rule (`& > * + *`) was tried
    14	 *    first and silently lost to the `margin: 0` in `zimmProductPrice.css.ts` and
    15	 *    `zimmProductDescription.css.ts` — equal specificity, and Emotion happened to inject the
    16	 *    child classes last. `gap` is set on the container and no child declaration can reach it.
    17	 *    The `play` in index.stories.tsx asserts the computed value so this cannot regress.
    18	 */
    19	
    20	/** DS: 20px between the name, price and description rows. Exactly `spacing.l`. */
    21	const SPACE_WITHIN_TEXT_GROUP = 'var(--zimm-scale-l)'; // 20px
    22	
    23	export const ZimmProductContent = {
    24	  baseStyle: {
    25	    display: 'flex',
    26	    flexDirection: 'column',
    27	    alignItems: 'flex-start',
    28	    gap: SPACE_WITHIN_TEXT_GROUP,
    29	  } satisfies SystemStyleObject,
    30	};
########## overrides/app/components/ui-kits/molecules/zimmProductContent/index.stories.tsx
     1	import type { Meta, StoryObj } from '@storybook/react-webpack5';
     2	import React from 'react';
     3	import { expect, within } from 'storybook/test';
     4	import { Box } from '@chakra-ui/react';
     5	import { ZimmProductContent } from '.';
     6	
     7	/** The real Shopper Products payload for 8637DS241 (ZimmermannAU, 2026-08-23). */
     8	const REAL_DESCRIPTION = [
     9	  'The Natura Mini Dress in Blue Birds from our Spring 2024 Collection, Natura. ',
    10	  'A long sleeve linen mini dress featuring a deep v-neckline with fitted bodice and full skirt.',
    11	  '<br><ul><li> Linen mini dress</li><li> Long sleeves with fluted cuffs </li>',
    12	  '<li> Crinoline hem </li><li> Invisible zip at centre back</li></ul>',
    13	].join('');
    14	
    15	const meta: Meta<typeof ZimmProductContent> = {
    16	  title: 'Commerce/ZimmProductContent',
    17	  component: ZimmProductContent,
    18	  argTypes: {
    19	    name: { control: 'text' },
    20	    price: { control: 'text' },
    21	    description: { control: 'text' },
    22	    headingLevel: { control: 'inline-radio', options: ['h1', 'h2', 'h3'] },
    23	  },
    24	  decorators: [
    25	    // The DS Content frame is 218px wide inside the info column; showing it at any other
    26	    // width makes the wrap behaviour and the 20px rhythm unreadable.
    27	    (Story: React.ComponentType) => (
    28	      <Box width="218px">
    29	        <Story />
    30	      </Box>
    31	    ),
    32	  ],
    33	};
    34	export default meta;
    35	
    36	type Story = StoryObj<typeof ZimmProductContent>;
    37	
    38	export const Default: Story = {
    39	  args: {
    40	    name: 'Natura Mini Dress',
    41	    headingLevel: 'h1',
    42	    price: '$795.00',
    43	    description: REAL_DESCRIPTION,
    44	  },
    45	};
    46	
    47	export const WithoutDescription: Story = {
    48	  name: 'Without description — rhythm collapses',
    49	  args: {
    50	    name: 'Natura Mini Dress',
    51	    headingLevel: 'h1',
    52	    price: '$795.00',
    53	    description: undefined,
    54	  },
    55	  play: async ({ canvasElement }) => {
    56	    const canvas = within(canvasElement);
    57	    const root = canvas.getByTestId('product-content');
    58	
    59	    // The description atom returns null, so the group must be exactly two rows with no
    60	    // trailing gap. A per-child marginBottom would leave 20px hanging under the price.
    61	    await expect(canvas.queryByTestId('product-description')).not.toBeInTheDocument();
    62	    await expect(root.children).toHaveLength(2);
    63	
    64	    // A flex gap applies only between rendered items, so two children means exactly one gap
    65	    // and no trailing space under the price.
    66	    await expect(getComputedStyle(root).rowGap).toBe('20px');
    67	  },
    68	};
    69	
    70	export const RhythmWithDescription: Story = {
    71	  name: 'Rhythm — 20px between every row',
    72	  args: {
    73	    name: 'Natura Mini Dress',
    74	    headingLevel: 'h1',
    75	    price: '$795.00',
    76	    description: '<p>A long sleeve linen mini dress.</p>',
    77	  },
    78	  play: async ({ canvasElement }) => {
    79	    const root = within(canvasElement).getByTestId('product-content');
    80	    await expect(root.children).toHaveLength(3);
    81	
    82	    // 20px = spacing.l, asserted as a computed value so a change to the token, to the recipe,
    83	    // or to its registration in theme/components/index.ts all surface here rather than only in
    84	    // a visual review. It also pins down that no child can out-specify the container.
    85	    await expect(getComputedStyle(root).rowGap).toBe('20px');
    86	    for (const child of Array.from(root.children)) {
    87	      await expect(getComputedStyle(child).marginTop).toBe('0px');
    88	    }
    89	  },
    90	};
    91	
    92	export const BlankDescription: Story = {
    93	  name: 'Description present but empty — also collapses',
    94	  // Business Manager can save the field as empty markup rather than clearing it, which is not
    95	  // the same input as `undefined` and has to reach the same rendering.
    96	  args: {
    97	    name: 'Natura Mini Dress',
    98	    headingLevel: 'h1',
    99	    price: '$795.00',
   100	    description: '<p></p>',
   101	  },
   102	  play: async ({ canvasElement }) => {
   103	    const canvas = within(canvasElement);
   104	    await expect(canvas.getByTestId('product-content').children).toHaveLength(2);
   105	    await expect(canvas.queryByTestId('product-description')).not.toBeInTheDocument();
   106	  },
   107	};

