     1	import React from 'react';
     2	import { chakra, useStyleConfig } from '@chakra-ui/react';
     3	import { isBlankRichText, parseRichText } from 'app/utils/richText';
     4	
     5	type ZimmProductDescriptionProps = {
     6	  /**
     7	   * The product's long description, as authored in Business Manager. Parsed into React nodes
     8	   * rather than injected as HTML — see `app/utils/richText` for why.
     9	   */
    10	  description?: string;
    11	};
    12	
    13	/**
    14	 * Atom — the product description. Renders nothing when the product has no description, so a
    15	 * caller can place it unconditionally.
    16	 */
    17	export const ZimmProductDescription = ({ description }: ZimmProductDescriptionProps) => {
    18	  const styles = useStyleConfig('ZimmProductDescription', {});
    19	  if (isBlankRichText(description)) return null;
    20	  const content = parseRichText(description);
    21	
    22	  return (
    23	    <chakra.div __css={styles} textStyle="body2" data-testid="product-description">
    24	      {content}
    25	    </chakra.div>
    26	  );
    27	};
