     1	/**
     2	 * Scoped to this atom's own contract per testing.md: does it render the parsed content, and
     3	 * does it collapse when there is nothing visible to show.
     4	 *
     5	 * `parseRichText`/`isBlankRichText` are mocked. Their behaviour — the whole allow-list and
     6	 * rejection matrix — is exhaustively proven in app/utils/richText.test.tsx, and re-asserting it
     7	 * here would be the duplicate coverage testing.md warns against. What is *not* proven anywhere
     8	 * else is that this component asks the right question before rendering.
     9	 */
    10	import React from 'react';
    11	import { describe, test, expect, vi, beforeEach } from 'vitest';
    12	import { render, screen } from '@testing-library/react';
    13	
    14	const parseRichText = vi.fn();
    15	const isBlankRichText = vi.fn();
    16	vi.mock('app/utils/richText', () => ({
    17	  parseRichText: (html?: string | null) => parseRichText(html),
    18	  isBlankRichText: (html?: string | null) => isBlankRichText(html),
    19	}));
    20	
    21	import { ZimmProductDescription } from './index';
    22	
    23	beforeEach(() => {
    24	  vi.clearAllMocks();
    25	});
    26	
    27	describe('ZimmProductDescription', () => {
    28	  test('renders the parsed nodes when there is visible content', () => {
    29	    isBlankRichText.mockReturnValue(false);
    30	    parseRichText.mockReturnValue([<p key="p">A long sleeve linen mini dress.</p>]);
    31	
    32	    render(<ZimmProductDescription description="<p>A long sleeve linen mini dress.</p>" />);
    33	
    34	    expect(screen.getByTestId('product-description')).toBeInTheDocument();
    35	    expect(screen.getByText('A long sleeve linen mini dress.')).toBeInTheDocument();
