########## overrides/app/components/ui-kits/atoms/zimmProductDescription/zimmProductDescription.css.ts
     1	import type { SystemStyleObject } from '@chakra-ui/react';
     2	
     3	/**
     4	 * Recipe for the product description.
     5	 *
     6	 * A recipe rather than Chakra props because the content is a parsed node tree — `<p>`, `<ul>`,
     7	 * `<li>`, `<br>` — and only a style object can reach those descendants. Chakra props and
     8	 * `textStyle` apply to the wrapper alone.
     9	 *
    10	 * Two deliberate non-inventions, both flagged for the designer:
    11	 *
    12	 *  - **List markers stay off.** Chakra's global reset already applies
    13	 *    `:where(ol, ul) { list-style-type: none }`, so the base PDP renders this list unbulleted
    14	 *    today. That is restated explicitly here so the rendering does not silently change if the
    15	 *    global registry is ever revised — it is not a design decision taken in this file. No DS
    16	 *    spec exists for the description's list treatment.
    17	 *  - **No responsive inset.** The mobile design insets the whole content column from the page
    18	 *    gutter, which the page owns (`grid.containerPadding.base`); nothing in the DS insets the
    19	 *    description within that column, so nothing is added here.
    20	 */
