cat > overrides/app/components/ui-kits/atoms/zimmProductPrice/index.tsx <<'EOF'
import React from 'react';
import { chakra, useStyleConfig } from '@chakra-ui/react';

const ZIMM_PRODUCT_PRICE_RECIPE = 'ZimmProductPrice';

type ZimmProductPriceProps = {
  /**
   * The price, already formatted for the storefront's locale and currency by the caller
   * (`intl.formatNumber` at the page). This atom does no formatting of its own so it stays
   * usable from Storybook without an intl provider.
   *
   * Optional because the page's mapper resolves an absent price to `''` rather than to a
   * formatted `NaN` — see `pages/product-detail/productInfo.ts`'s `selectPdpProductInfo` and
   * the assertion it carries in `productInfo.test.ts`. That empty string reaches this atom
   * unchanged and the decision not to render is taken here.
   */
  price?: string;
  /** Reserved for SFCC-194's was/now treatment; only `default` is implemented today. */
  variant?: 'default';
};

/**
 * Atom — the single, full product price. Styling lives in `zimmProductPrice.css.ts` and is
 * consumed through the theme, per the one-canonical-styling-surface rule.
 *
 * Renders nothing when there is no price, so a caller can place it unconditionally — the same
 * contract as `ZimmProductDescription`. Rendering an empty `<p>` instead would still take a
 * flex `gap` in `ZimmProductContent`'s column, leaving a hole where the price should be.
 */
export const ZimmProductPrice = ({ price, variant = 'default' }: ZimmProductPriceProps) => {
  // Guard below the hook, never above it: an early return before `useStyleConfig` makes the
  // hook call conditional, which `react-hooks/rules-of-hooks` reports as an error rather than a
  // warning. Same ordering as `ZimmProductDescription` and `ZimmProductStyleCode`.
  const styles = useStyleConfig(ZIMM_PRODUCT_PRICE_RECIPE, { variant });
  if (!price) return null;

  return (
    <chakra.p __css={styles} textStyle="price" data-testid="product-price">
      {price}
    </chakra.p>
  );
};
EOF
npx prettier --check overrides/app/components/ui-kits/atoms/zimmProductPrice/index.tsx

cat > overrides/app/components/ui-kits/atoms/zimmProductPrice/index.test.tsx <<'EOF'
/**
 * Scoped to this atom's own contract per testing.md: given a formatted string or nothing, does
 * it render the right branch.
 *
 * Formatting is deliberately not asserted here — it happens at the page
 * (`selectPdpProductInfo`, proven in pages/product-detail/productInfo.test.ts) and this atom
 * renders whatever string it is handed. What is not proven anywhere else is the absent branch:
 * the mapper resolves a missing price to `''`, so the empty case is a real production path and
 * not a defensive edge case.
 */
import React from 'react';
import { describe, test, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ZimmProductPrice } from './index';

describe('ZimmProductPrice', () => {
  test('renders the caller-formatted string verbatim', () => {
    render(<ZimmProductPrice price="HK$6,200.00" />);
    // Verbatim, not re-formatted: the currency symbol, grouping and decimals are all the
    // page's decisions, and re-deriving any of them here would diverge per storefront.
    expect(screen.getByTestId('product-price').textContent).toBe('HK$6,200.00');
  });

  test.each([undefined, ''])('renders nothing for %s', (price) => {
    render(<ZimmProductPrice price={price} />);
    // `''` is what the page's mapper produces for a product with no price, so this branch is
    // reached in production. An empty styled node would still consume a gap in
    // ZimmProductContent's flex column, leaving a visible hole between name and description.
    expect(screen.queryByTestId('product-price')).not.toBeInTheDocument();
  });
});
EOF
npx prettier --check overrides/app/components/ui-kits/atoms/zimmProductPrice/index.test.tsx

