    // rhythm reads as arbitrary whitespace rather than as the design's spacing.
    (Story: React.ComponentType) => (
      <Box width="218px">
        <Story />
      </Box>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof ZimmProductMeta>;

export const Default: Story = {
  args: {
    modelInfo: 'Model is 5’9.5"/178cm, bust size 32C/10C and wears a size 0',
    styleCode: '8637DS241',
  },
  play: async ({ canvasElement }) => {
    const root = within(canvasElement).getByTestId('product-meta');

    // 28px, asserted as a computed value for the same reason ZimmProductContent's
    // RhythmWithDescription does it: a change to SPACE_META_ROW, to the recipe, or to the
    // recipe's registration in theme/components/index.ts all surface here rather than only in a
    // visual review. That last one has no other detection anywhere — an unregistered recipe
    // makes useMultiStyleConfig return an empty object, which tsc and eslint both accept.
    //
    // `rowGap`, not `gap`: a real browser expands the shorthand, so reading `gap` off a computed
    // style returns '' here. This is also why the assertion cannot live in the Vitest suite —
    // jsdom does not expand it, and there is no ChakraProvider there to resolve the recipe.
    await expect(getComputedStyle(root).rowGap).toBe('28px');

    // The same const drives the space above the block, so pin both. Asserting only the gap is
    // how the two hops silently drift apart.
    await expect(getComputedStyle(root).paddingTop).toBe('28px');
  },
};

export const StyleCodeOnly: Story = {
  name: 'No model copy — style code alone',
  // The common shape in the live catalogue: `c_modelFit` is unpopulated on most products, so
  // the block usually renders as a single row.
  args: { modelInfo: undefined, styleCode: '8637DS241' },
};

export const Empty: Story = {
  name: 'Neither field — the whole block collapses',
  args: { modelInfo: undefined, styleCode: undefined },
  play: async ({ canvasElement }) => {
    // The wrapper carries a paddingTop, which does not collapse the way a gap does — so an
    // empty block would be 28px of visible space below the accordions.
    await expect(within(canvasElement).queryByTestId('product-meta')).not.toBeInTheDocument();
  },
};
